/* Static content data for Waqt24 (Du'a, Hadees, Ilm names/words/myths, quiz bank). Loaded before the main script in index.html. */
const DUAS = [
  {cat:'Roz Marra', title:'Sone ki Dua', arabic:'اَللّٰھُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا', translit:"Allahumma bismika amutu wa ahya.", meaning:'Aye Allah! Main Tere hi naam par marta (sota) hoon aur zinda hota (jagta) hoon.', ref:'Sahih Bukhari'},
  {cat:'Roz Marra', title:'Jagne ki Dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', translit:'Alhamdu lillahil-lazi ahyana ba\'da ma amatana wa ilaihin-nushur', meaning:'Sab tareef Allah ke liye hai jisne humein maut ke baad zinda kiya, aur usi ki taraf lautna hai.', ref:'Sahih Bukhari'},
  {cat:'Khana', title:'Khana Shuru Karne ki Dua', arabic:'بِسْمِ اللَّهِ', translit:'Bismillah', meaning:'Allah ke naam se.', ref:'Sahih Bukhari'},
  {cat:'Khana', title:'Khana Khatam Karne ki Dua', arabic:'الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ', translit:'Alhamdulillahillazi at\'amani haza wa razaqnihi min ghairi haulin minni wa la quwwatin.', meaning:'Tamam taarifain us Allah ke liye hain jisne mujhe yeh khana khilaya aur meri taqat ya qudrat na hone ke bawajood mujhe yeh ata farmaya.', ref:'Abu Dawood, Tirmidhi, Ibn Majah', info:'Hadees: Hazrat Mu\'adh bin Anas (RA) se riwayat hai ki Nabi ﷺ ne farmaya: jo shakhs khana khaye aur phir yeh dua padhe, uske pichle aur aainda ke gunah bakhsh diye jayenge. Yeh dua khane ki niamat par shukr ka izhaar hai, aur iss baat ka iqrar ki rizq Allah ki taraf se hai, apni taqat ya qudrat se nahi.'},
  {cat:'Safar', title:'Safar ki Dua', arabic:'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ', translit:'Subhanal-lazi sakhkhara lana haza wa ma kunna lahu muqrinin', meaning:'Pak hai woh Zaat jisne is sawari ko humare kaabu mein diya.', ref:'Sahih Muslim'},
  {cat:'Masjid', title:'Masjid Mein Dakhil Hone ki Dua', arabic:'اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ', translit:'Allahummaf-tah li abwaba rahmatik', meaning:'Ae Allah, mere liye apni rehmat ke darwaze khol de.', ref:'Sahih Muslim'},
  {cat:'Masjid', title:'Masjid Se Nikalne ki Dua', arabic:'اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ', translit:'Allahumma inni as\'aluka min fadlik', meaning:'Ae Allah, main aapse aapke fazl ka sawal karta hoon.', ref:'Sahih Muslim'},
  {cat:'Pareshani', title:'Pareshani Ke Waqt ki Dua', arabic:'حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ', translit:"Hasbunallahu wa ni'mal wakil", meaning:'Allah humare liye kaafi hai aur woh behtareen kaarsaaz hai.', ref:'Qur’an 3:173'},
  {cat:'Ghar', title:'Ghar Mein Dakhil Hone ki Dua', arabic:'بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى رَبِّنَا تَوَكَّلْنَا', translit:"Bismillahi walajna wa bismillahi kharajna wa 'ala rabbina tawakkalna", meaning:'Allah ke naam se hum andar aaye aur Allah ke naam se nikle, aur apne Rab par bharosa kiya.', ref:'Abu Dawood'},
  {cat:'Ramzan', title:'Iftar karne ki dua', arabic:'ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ', translit:"Zahabaz-zama'u wabtallatil-'uruqu wa thabatal-ajru in sha Allah", meaning:'Pyaas chali gayi, rag-tarein tar ho gayi, aur agar Allah ne chaha to ajar sabit ho gaya.', ref:'Abu Dawood'},
  {cat:'Rabbana', title:"Qabooliyat Ki Dua", arabic:"رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ", translit:"Rabbana taqabbal minna innaka antas Sami'ul 'Aleem", meaning:"Ae hamare Rab, hamari taraf se (yeh amal) qabool farma. Beshak Tu hi sunne wala aur jaanne wala hai.", ref:"Qur’an 2:127", tags:["Quranic", "Rabbana", "Qabooliyat"]},
  {cat:'Rabbana', title:"Islam Par Qaim Rehne Ki Dua", arabic:"رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ", translit:"Rabbana waj'alna muslimaini laka wa min zurriyyatina ummatam muslimatal laka wa arina manasikana wa tub 'alayna innaka antat Tawwabur Raheem", meaning:"Ae hamare Rab, humein apna farmabardar bana aur hamari aulad mein se bhi apni farmabardar ummat paida kar. Humein hamare ibadat ke tareeqe dikha aur hamari tauba qabool kar. Beshak Tu tauba qabool karne wala, meherbaan hai.", ref:"Qur’an 2:128", tags:["Quranic", "Rabbana", "Islam"]},
  {cat:'Rabbana', title:"Duniya Aur Aakhirat Ki Bhalai", arabic:"رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana atina fid dunya hasanatanw wa fil akhirati hasanatanw wa qina 'adhaban Nar", meaning:"Ae hamare Rab, humein duniya mein bhalai de aur aakhirat mein bhi bhalai de, aur humein aag ke azaab se bacha le.", ref:"Qur’an 2:201", tags:["Quranic", "Rabbana", "Duniya Aur Aakhirat"]},
  {cat:'Rabbana', title:"Sabr Aur Sabit Qadmi Ki Dua", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ", translit:"Rabbana afrigh 'alayna sabranw wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par sabr undel de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 2:250", tags:["Quranic", "Rabbana", "Sabr"]},
  {cat:'Rabbana', title:"Bhool Chook Ki Maafi", arabic:"رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ", translit:"Rabbana la tu'akhidhna in nasina aw akhta'na", meaning:"Ae hamare Rab, agar hum bhool jayein ya ghalti kar baithein to hamari pakad na kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Tauba"]},
  {cat:'Rabbana', title:"Bhari Bojh Se Hifazat", arabic:"رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ", translit:"Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alal-ladhina min qablina", meaning:"Ae hamare Rab, hum par woh bojh na daal jo Tu ne hum se pehle logon par daala tha.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Hifazat"]},
  {cat:'Rabbana', title:"Taqat Se Zyada Imtihan Na Ho", arabic:"رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ", translit:"Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, anta mawlana fansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hum par utna bojh na daal jitni humein taqat na ho. Humein maaf kar, bakhsh de aur hum par reham kar. Tu hi hamara Maula (kaarsaaz) hai, to kafir qaum par hamari madad kar.", ref:"Qur’an 2:286", tags:["Quranic", "Rabbana", "Maghfirat"]},
  {cat:'Rabbana', title:"Dil Ko Haq Par Qaim Rakh", arabic:"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ", translit:"Rabbana la tuzigh qulubana ba'da idh hadaytana wa hab lana min ladunka rahmah, innaka antal Wahhab", meaning:"Ae hamare Rab, hidayat dene ke baad hamare dilon ko seedhe raste se mat phera, aur apni taraf se hum par rehmat farma. Beshak Tu hi bahut ata karne wala hai.", ref:"Qur’an 3:8", tags:["Quranic", "Rabbana", "Hidayat"]},
  {cat:'Rabbana', title:"Qiyamat Par Yaqeen Ki Dua", arabic:"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ", translit:"Rabbana innaka jami'un-nasi liyawmil la raiba fih, innal laha la yukhliful mi'ad", meaning:"Ae hamare Rab, beshak Tu hi tamam logon ko us din ke liye jama karega jis mein koi shak nahi. Beshak Allah apna wada khilaf nahi karta.", ref:"Qur’an 3:9", tags:["Quranic", "Rabbana", "Qiyamat"]},
  {cat:'Rabbana', title:"Iman Aur Gunahon Ki Maafi", arabic:"رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana innana amanna faghfir lana dhunubana wa qina 'adhaban Nar", meaning:"Ae hamare Rab, hum emaan le aaye hain, to hamare gunah bakhsh de aur hamein aag ke azaab se bacha le.", ref:"Qur’an 3:16", tags:["Quranic", "Rabbana", "Maghfirat"]},
  {cat:'Rabbana', title:"Gawahi Mein Shamil Hone Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا بِمَآ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ", translit:"Rabbana amanna bima anzalta wattaba'nar Rasula faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan laaye us par jo Tu ne nazil kiya aur Rasool ki pairwi ki, to hamein gawahon ke saath likh le.", ref:"Qur’an 3:53", tags:["Quranic", "Rabbana", "Iman"]},
  {cat:'Rabbana', title:"Gunah Aur Hadd Se Barhi Zyadati Ki Maafi", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِىٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ", translit:"Rabbana ghfir lana dhunubana wa israfana fi amrina wa thabbit aqdamana wansurna 'alal qawmil kafirin", meaning:"Ae hamare Rab, hamare gunah aur hamare kaamon mein hui hadd se barhi zyadatiyan bakhsh de, hamare qadam jamaye rakh aur kafir qaum par hamari madad kar.", ref:"Qur’an 3:147", tags:["Quranic", "Rabbana", "Maghfirat"]},
  {cat:'Rabbana', title:"Kainat Ki Hikmat Aur Jahannam Se Panah", arabic:"رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ", translit:"Rabbana ma khalqta hadha batila, subhanaka faqina 'adhaban Nar", meaning:"Ae hamare Rab, Tu ne yeh sab kuch bekaar paida nahi kiya. Tu paak hai, to hamein aag ke azaab se bacha le.", ref:"Qur’an 3:191", tags:["Quranic", "Rabbana", "Jahannam"]},
  {cat:'Rabbana', title:"Ruswai Se Panah Ki Dua", arabic:"رَبَّنَآ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَيۡتَهُۥۖ وَمَا لِلظَّٰلِمِينَ مِنۡ أَنصَارٖ", translit:"Rabbana innaka man tudkhilin Nara faqad akhzaytah, wa ma lizzalimina min ansar", meaning:"Ae hamare Rab, beshak jisko Tu aag mein daakhil kare, usay Tu ne rusva kar diya. Zalimon ke liye koi madadgar nahi.", ref:"Qur’an 3:192", tags:["Quranic", "Rabbana", "Jahannam"]},
  {cat:'Rabbana', title:"Pukarne Wale Ki Pukaar Par Iman", arabic:"رَبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ", translit:"Rabbana innana sami'na munadiyany yunadi lil iymani an aminu bi rabbikum fa amanna", meaning:"Ae hamare Rab, hum ne ek pukarne wale ko suna jo iman ki taraf bula raha tha ki apne Rab par emaan lao, to hum emaan le aaye.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Iman"]},
  {cat:'Rabbana', title:"Gunahon Ki Safai Aur Nek Logon Ke Saath Maut", arabic:"رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ", translit:"Rabbana faghfir lana dhunubana wa kaffir 'anna sayyi'atina wa tawaffana ma'al abrar", meaning:"Ae hamare Rab, hamare gunah bakhsh de, hamari burayiyan mita de aur hamein nek logon ke saath maut de.", ref:"Qur’an 3:193", tags:["Quranic", "Rabbana", "Nek Log"]},
  {cat:'Rabbana', title:"Wade Ki Pooran Ki Dua, Qiyamat Ki Ruswai Se Bachao", arabic:"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۗ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ", translit:"Rabbana wa atina ma wa'attana 'ala rusulika wa la tukhzina yawmal qiyamah, innaka la tukhlifu al-mi'ad", meaning:"Ae hamare Rab, jo wada Tu ne apne Rasoolon ke zariye kiya hai woh hamein ata kar aur qiyamat ke din hamein ruswa na kar. Beshak Tu wade ke khilaf nahi karta.", ref:"Qur’an 3:194", tags:["Quranic", "Rabbana", "Qiyamat"]},
  {cat:'Rabbana', title:"Gawahi Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِينَ", translit:"Rabbana amanna faktubna ma'ash shahidin", meaning:"Ae hamare Rab, hum emaan le aaye, to hamein gawahon mein likh le.", ref:"Qur’an 5:83", tags:["Quranic", "Rabbana", "Iman"]},
  {cat:'Rabbana', title:"Rizq Ki Dua (Dastarkhwan)", arabic:"رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ", translit:"Rabbana anzil 'alayna ma'idatam minas sama'i takunu lana 'idal li awwalina wa akhirina wa ayatan minka warzuqna wa anta khayrur raziqin", meaning:"Ae hamare Rab, hum par aasmaan se khaane ka dastarkhwan utaar, jo hamare liye, hamare pehlon aur baad waalon ke liye eid ho aur Teri taraf se ek nishani ho. Hamein rizq de, Tu behtareen rizq dene wala hai.", ref:"Qur’an 5:114", tags:["Quranic", "Rabbana", "Rizq"]},
  {cat:'Rabbana', title:"Apne Nafs Par Zulm Ka Iqrar", arabic:"رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ", translit:"Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal khasirin", meaning:"Ae hamare Rab, hum ne apni jaanon par zulm kiya. Agar Tu hamein maaf na kare aur hum par reham na kare to hum yaqeenan nuqsan uthane walon mein se honge.", ref:"Qur’an 7:23", tags:["Quranic", "Rabbana", "Tauba"]},
  {cat:'Rabbana', title:"Zalim Logon Ki Sohbat Se Panah", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ", translit:"Rabbana la taj'alna ma'al qawmiz zalimin", meaning:"Ae hamare Rab, hamein zalim logon ke saath shumar na kar.", ref:"Qur’an 7:47", tags:["Quranic", "Rabbana", "Sohbat"]},
  {cat:'Rabbana', title:"Haq Ke Saath Faisla", arabic:"رَبَّنَا ٱفۡتَحۡ بَيۡنَنَا وَبَيۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَيۡرُ ٱلۡفَٰتِحِينَ", translit:"Rabbana iftah bayna wa bayna qawmina bil haqqi wa anta khayrul fatihin", meaning:"Ae hamare Rab, hamare aur hamari qaum ke darmiyan haq ke saath faisla kar de, aur Tu behtareen faisla karne wala hai. (Hazrat Shuaib AS ki dua)", ref:"Qur’an 7:89", tags:["Quranic", "Rabbana", "Haq"]},
  {cat:'Rabbana', title:"Sabr Aur Iman Par Maut", arabic:"رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ", translit:"Rabbana afrigh 'alayna sabranw wa tawaffana muslimin", meaning:"Ae hamare Rab, hum par sabr undel de aur hamein musalman hone ki haalat mein maut de. (Hazrat Musa AS ki dua)", ref:"Qur’an 7:126", tags:["Quranic", "Rabbana", "Sabr"]},
  {cat:'Rabbana', title:"Zalim Qaum Ke Fitne Se Nijaat", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلۡقَوۡمِ ٱلظَّـٰلِمِينَ وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ", translit:"Rabbana la taj'alna fitnatal lil qawmiz zalimin, wa najjina bi rahmatika minal qawmil kafirin", meaning:"Ae hamare Rab, hamein zalim qaum ke liye fitna na bana, aur apni rehmat se hamein kafir qaum se nijaat de.", ref:"Qur’an 10:85-86", tags:["Quranic", "Rabbana", "Hifazat"]},
  {cat:'Rabbana', title:"Allah Se Kuch Chhupa Nahi", arabic:"رَبَّنَآ إِنَّكَ تَعۡلَمُ مَا نُخۡفِى وَمَا نُعۡلِنُۗ وَمَا يَخۡفَىٰ عَلَى ٱللَّهِ مِن شَىۡءٖ فِى ٱلۡأَرۡضِ وَلَا فِى ٱلسَّمَآءِ", translit:"Rabbana innaka ta'lamu ma nukhfi wa ma nu'lin, wa ma yakhfa 'alal lahi min shay'in fil ardi wa la fis sama'", meaning:"Ae hamare Rab, beshak Tu jaanta hai jo hum chhupate hain aur jo zahir karte hain. Zameen aur aasmaan mein koi cheez Allah se chhupi nahi.", ref:"Qur’an 14:38", tags:["Quranic", "Rabbana", "Ilm-e-Ilahi"]},
  {cat:'Rabbana', title:"Namaz Qaim Karne Ki Dua (Hazrat Ibrahim AS)", arabic:"رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ", translit:"Rabbij 'alni muqimas salati wa min dhurriyyati, Rabbana wa taqabbal du'a", meaning:"Ae mere Rab, mujhe namaz qaim karne wala bana, aur meri aulad mein se bhi. Ae hamare Rab, meri dua qabool kar.", ref:"Qur’an 14:40", tags:["Quranic", "Rabbana", "Namaz"]},
  {cat:'Rabbana', title:"Maghfirat Walidain Aur Momineen Ke Liye", arabic:"رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ", translit:"Rabbanagh-fir li wa li walidayya wa lil mu'minina yawma yaqumul hisab", meaning:"Ae hamare Rab, mujhe, mere walidain aur tamam momin logon ko us din bakhsh de jis din hisaab qaim hoga.", ref:"Qur’an 14:41", tags:["Quranic", "Rabbana", "Walidain"]},
  {cat:'Rabbana', title:"Rehmat Aur Hidayat Ki Dua (Ashab-e-Kahf)", arabic:"رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا", translit:"Rabbana atina min ladunka rahmatan wa hayyi' lana min amrina rashada", meaning:"Ae hamare Rab, hamein apni taraf se rehmat ata kar aur hamare kaam mein hamein seedha raasta (hidayat) de. (Ashab-e-Kahf ki dua)", ref:"Qur’an 18:10", tags:["Quranic", "Rabbana", "Hidayat"]},
  {cat:'Rabbana', title:"Zulm Aur Sarkashi Ka Khauf", arabic:"رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ", translit:"Rabbana innana nakhafu an yafruta 'alayna aw an yatgha", meaning:"Ae hamare Rab, hamein darr hai ki woh hum par jaldi saza na kar de ya sarkashi na kare. (Hazrat Harun aur Musa AS ki dua)", ref:"Qur’an 20:45", tags:["Quranic", "Rabbana", "Hifazat"]},
  {cat:'Rabbana', title:"Maghfirat Aur Reham Ki Dua", arabic:"رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ", translit:"Rabbana amanna faghfir lana warhamna wa anta khayrur rahimin", meaning:"Ae hamare Rab, hum emaan laaye, to hamein bakhsh de aur hum par reham kar, aur Tu sab se behtar reham karne wala hai.", ref:"Qur’an 23:109", tags:["Quranic", "Rabbana", "Rehmat"]},
  {cat:'Rabbana', title:"Jahannam Ke Azaab Se Panah", arabic:"رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَامًا إِنَّهَا سَآءَتۡ مُسۡتَقَرّٗا وَمُقَامٗا", translit:"Rabbana isrif 'anna 'adhaba jahannam, inna 'adhabaha kana gharama, innaha sa'at mustaqarranw wa muqama", meaning:"Ae hamare Rab, humse Jahannam ka azaab door rakh. Beshak uska azaab laazmi aur chipakne wala hai. Woh bura thikana aur theharne ki jagah hai.", ref:"Qur’an 25:65-66", tags:["Quranic", "Rabbana", "Jahannam"]},
  {cat:'Rabbana', title:"Aankhon Ki Thandak, Nek Aulad Aur Imam", arabic:"رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّـٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا", translit:"Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yunin waj'alna lil muttaqina imama", meaning:"Ae hamare Rab, hamein hamari biwiyon aur aulad se aankhon ki thandak ata kar aur hamein mutteqi logon ka imam (rehnumaa) bana.", ref:"Qur’an 25:74", tags:["Quranic", "Rabbana", "Aulad"]},
  {cat:'Rabbana', title:"Shukr Aur Bakhshish", arabic:"رَبَّنَا لَغَفُورٌ شَكُورٌ", translit:"Rabbana la ghafurun shakur", meaning:"Ae hamare Rab, beshak Tu bakhshne wala aur qadar karne wala hai.", ref:"Qur’an 35:34", tags:["Quranic", "Rabbana", "Shukr"]},
  {cat:'Rabbana', title:"Tauba Karne Walon Ki Maghfirat Aur Jahannam Se Hifazat", arabic:"رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ", translit:"Rabbana wasi'ta kulla shay'in rahmatanw wa 'ilman faghfir lilladhina taabu wattaba'u sabilaka wa qihim 'adhabal jahim", meaning:"Ae hamare Rab, Tu ne har cheez ko apni rehmat aur ilm mein samoya hua hai. Un logon ko bakhsh de jo tauba karte hain aur Tere raaste ki pairwi karte hain, aur unhein jahannam ke azaab se bacha le.", ref:"Qur’an 40:7", tags:["Quranic", "Rabbana", "Tauba"]},
  {cat:'Rabbana', title:"Jannat Mein Walidain, Aulad Aur Biwiyon Ke Saath", arabic:"رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ", translit:"Rabbana wa adkhilhum jannati 'adnin allati wa'attahum wa man salaha min aba'ihim wa azwajihim wa dhurriyyatihim, innaka antal 'Azizul Hakim. Wa qihimus sayyi'at, wa man taqis sayyi'ati yawma'idhin faqad rahimtah, wa dhalika huwal fawzul 'adhim", meaning:"Ae hamare Rab, unhein Adan ke baghon mein daakhil kar jo Tu ne unse wada kiya hai, aur unke baap-dada, biwiyon aur aulad mein se jo nek hain unhein bhi. Beshak Tu hi zabardast aur hikmat wala hai. Unhein buraiyon se bacha, aur jisko Tu us din buraiyon se bacha le, us par Tu ne reham kiya. Yehi badi kamyabi hai.", ref:"Qur’an 40:8-9", tags:["Quranic", "Rabbana", "Jannat"]},
  {cat:'Rabbana', title:"Bhai Bandon Ke Liye Maghfirat, Dil Mein Kina Na Ho", arabic:"رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلۡإِيمَٰنِ وَلَا تَجۡعَلۡ فِي قُلُوبِنَا غِلّٗا لِّلَّذِينَ ءَامَنُواْ", translit:"Rabbana ghfir lana wa li ikhwanina alladhina sabaquna bil iman, wa la taj'al fi qulubina ghillal lilladhina amanu", meaning:"Ae hamare Rab, hamein aur hamare un bhaiyon ko bakhsh de jo hum se pehle emaan laaye, aur hamare dilon mein emaan walon ke liye kina na rakh.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Ukhuwwat"]},
  {cat:'Rabbana', title:"Rauf Aur Raheem Rab Ki Pukaar", arabic:"رَبَّنَآ إِنَّكَ رَءُوفٞ رَّحِيمٞ", translit:"Rabbana innaka ra'ufur rahim", meaning:"Ae hamare Rab, beshak Tu bahut shafqat karne wala aur reham karne wala hai.", ref:"Qur’an 59:10", tags:["Quranic", "Rabbana", "Rehmat"]},
  {cat:'Rabbana', title:"Tawakkul Aur Akhirat Ki Taraf Wapsi", arabic:"رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ", translit:"Rabbana 'alayka tawakkalna wa ilayka anabna wa ilaykal masir", meaning:"Ae hamare Rab, hamne Tujh par tawakkul kiya, Teri taraf rujoo kiya aur Teri hi taraf lautna hai.", ref:"Qur’an 60:4", tags:["Quranic", "Rabbana", "Tawakkul"]},
  {cat:'Rabbana', title:"Kafiron Ke Fitne Se Hifazat (Hazrat Ibrahim AS)", arabic:"رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ وَٱغۡفِرۡ لَنَا رَبَّنَآۖ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ", translit:"Rabbana la taj'alna fitnatal lilladhina kafaru waghfir lana rabbana, innaka antal 'Azizul Hakim", meaning:"Ae hamare Rab, hamein kafiron ke liye fitna (aazmaish ka zariya) na bana, aur hamein bakhsh de. Beshak Tu zabardast aur hikmat wala hai.", ref:"Qur’an 60:5", tags:["Quranic", "Rabbana", "Hifazat"]},
  {cat:'Rabbana', title:"Noor Ki Takmeel Aur Maghfirat", arabic:"رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ", translit:"Rabbana atmim lana nurana waghfir lana, innaka 'ala kulli shay'in qadir", meaning:"Ae hamare Rab, hamare liye hamara noor mukammal kar de aur hamein bakhsh de. Beshak Tu har cheez par qadir hai.", ref:"Qur’an 66:8", tags:["Quranic", "Rabbana", "Noor"]},
  {cat:"Pareshani", title:"Gham, Susti Aur Qarz Se Panah Ki Dua", arabic:"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ", translit:"Allahumma inni a'udhu bika minal-hammi wal-hazan, wa a'udhu bika minal-'ajzi wal-kasal, wa a'udhu bika minal-jubni wal-bukhl, wa a'udhu bika min ghalabatid-dayni wa qahrir-rijal.", meaning:"Ya Allah! Main Tujh se fikr aur gham se panah maangta hoon, aur be-basi aur susti se panah maangta hoon. Main Tujh se buzdili aur bukhl se panah maangta hoon, aur qarz ke bojh aur logon ke ghalib aa jane se Teri panah chahta hoon.", ref:"Sahih Bukhari", tags:["Sunnah", "Pareshani", "Hifazat"]},
];
